	struct net *net = dev_net_rcu(skb->dev);
	struct sock *sk;
	int iif, sdif;

	sk = udp_tunnel_sk(net, false);
	if (sk && dport == htons(sk->sk_num))
		return sk;

	inet_get_iif_sdif(skb, &iif, &sdif);

	return __udp4_lib_lookup(net, iph->saddr, sport,
				 iph->daddr, dport, iif, sdif, NULL);
}

